    "text": "Open I → Food Wiki for the full café pantry. It has a search box and categories for ingredients, small bakes, bread and pastries, cakes, sandwiches, paninis, savoury bakes, soups, breakfasts, fruit pots and greenhouse plants. It distinguishes learned recipes from pages still to learn. The six starter bakes are Plain scone, Butter shortbread, Chocolate-chip cookie, Vanilla muffin, Oat flapjack and Rustic bread roll. Later recipes come from lessons, recipe purchases or their named stories. Knowing a recipe is separate from having the counter and ingredients to prepare it.",
